//! The cockpit's protocol types, generated from these (theseus-0g4; the owner's
//! call, 2026-10-01): one file per type in `cockpit/src/protocol.gen/`, and
//! `index.ts` exporting them all. `cockpit/src/protocol.ts` re-exports them
//! beside the client, and the cockpit imports it as `@protocol`.
//!
//! The test writes the files, and the gate fails when they differ from the
//! commit: a Rust type changed without its TypeScript fails the gate. Large
//! integers are `number`, since the wire is JSON and `JSON.parse` reads
//! numbers. A `serde_json::Value` field says its TypeScript type itself
//! (`#[ts(type = "...")]`).
//!
//! The place: the directory sat in `web/src/` until the Observatory retired,
//! and moved into the cockpit byte for byte (theseus-vm3n.6). `.gen` says
//! nobody edits it.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use ts_rs::{Config, TS};

use crate::*;

/// Every wire type, exported with its dependencies.
macro_rules! export {
    ($cfg:expr; $($t:ty),* $(,)?) => {
        $(<$t as TS>::export_all($cfg).unwrap_or_else(|e| panic!("{}: {e}", stringify!($t)));)*
    };
}

fn out_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../cockpit/src/protocol.gen")
}

/// Clears the generated files, so a type that went away takes its file with it, and writes the value files, which no
/// type makes. The test's own length is clippy's `too_many_lines` ceiling, so the clearing lives here.
fn reset(dir: &Path) {
    for e in std::fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if p.extension().is_some_and(|x| x == "ts") {
            std::fs::remove_file(p).unwrap();
        }
    }
    write_expiring_tools(dir);
}

/// The one list a client needs as a value and not a type (theseus-lrc3m): the tools whose question expires, written
/// from `work::ask::EXPIRING_TOOLS`, so the cockpit's `heldquestion.ts` imports it and keeps no copy. A tool added to
/// the Rust list changes this file, and the gate's "protocol types" check fails until the change is committed.
fn write_expiring_tools(dir: &Path) {
    let tools = crate::work::ask::EXPIRING_TOOLS
        .map(|t| format!("\"{t}\""))
        .join(", ");
    let text = format!(
        "// This file was generated by theseus-protocol's `ts` test, from `work::ask::EXPIRING_TOOLS`. Do not edit this file manually.\n\
         // The tools whose question still expires at its life; any other question is held until it is answered.\n\
         export const EXPIRING_TOOLS = [{tools}] as const;\n"
    );
    std::fs::write(dir.join("ExpiringTools.ts"), text).unwrap();
}

/// The types this crate declares, by its sources: (file, name, derives `TS`). Every source file of the crate is read
/// (issue 15), not a list of them: a list named 29 files and missed the rest, so a type declared in a file it did not
/// name was never checked.
fn declared() -> Vec<(String, String, bool)> {
    declared_in(&Path::new(env!("CARGO_MANIFEST_DIR")).join("src"))
}

/// Every `.rs` file under `dir`: its path relative to `root`, and its text.
fn sources(root: &Path, dir: &Path, out: &mut Vec<(String, String)>) {
    for e in std::fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if p.is_dir() {
            sources(root, &p, out);
        } else if p.extension().is_some_and(|x| x == "rs") {
            let rel = p.strip_prefix(root).unwrap().to_string_lossy().into_owned();
            out.push((rel, std::fs::read_to_string(&p).unwrap()));
        }
    }
}

/// The types the sources under `root` declare: a line that starts `pub struct ` or `pub enum `, and whether the
/// attributes and docs above it derive `TS`.
fn declared_in(root: &Path) -> Vec<(String, String, bool)> {
    let mut files = Vec::new();
    sources(root, root, &mut files);
    files.sort();
    let mut out = Vec::new();
    for (file, src) in files {
        let lines: Vec<&str> = src.lines().collect();
        for (i, l) in lines.iter().enumerate() {
            let Some(rest) = l
                .strip_prefix("pub struct ")
                .or_else(|| l.strip_prefix("pub enum "))
            else {
                continue;
            };
            let name: String = rest
                .chars()
                .take_while(|c| c.is_alphanumeric() || *c == '_')
                .collect();
            let ts = lines[..i]
                .iter()
                .rev()
                .take_while(|a| a.starts_with("#[") || a.starts_with("///"))
                .any(|a| a.contains("ts_rs::TS"));
            out.push((file.clone(), name, ts));
        }
    }
    out
}

/// The public types that never cross the wire, as `<file> <name>`, each with why: no method, notification or result
/// carries them, so they have no TypeScript. Any other public type is a wire type and the test below holds it to one.
const NOT_WIRE: &[&str] = &[
    "diff.rs Kind",            // a diff row's kind, for rendering
    "diff.rs Row",             // a numbered diff row, for rendering
    "flow.rs FlowInfo",        // the core's view of a loaded flow; no method returns it
    "flow.rs FlowHandback",    // what a flow hands the model, as a tool's result
    "grants.rs SessionGrant",  // what edits mode's rule reads, in the core
    "initiative.rs Proactive", // the order of first messages, in the core
    "jsonrpc.rs Incoming",     // a message as read, before it is one of the wire's types
    "outbox.rs Receipt",       // a channel's receipt, as the outbox stores it
    "own_command.rs Way",      // what a verb of the command line does, for the shell's answer
    "own_command.rs Entry",    // one row of that table
    "own_command.rs Answered", // the tool a shell look is answered with, in the core
    "routines.rs RunMark",     // a run's stored mark
    "routines.rs RoutinePing", // a routine's stored memory of its pings
    "rsi.rs SelfRowKind",      // the table of `self.*` row kinds
    "sessions.rs StateRule",   // the windows a session's state is derived with
    "sessions.rs StateOf",     // what the state rule reads of a session
    "warm.rs Typist",          // a client's own memory of whom it told
    "why.rs WhyInput",         // what a `why` is built from
    "why.rs Why",              // a `why`'s sections, before they are lines
    "why.rs ToolCalled",       // a tool call, as a `why` counts it
    "notices/burst.rs Burst",  // the burst rule's memory, in a client
    "work/ask.rs AskOption",   // `owner_ask`'s input: a tool's, inside a call's `input`
    "work/ask.rs AskInput",    // `owner_ask`'s input: a tool's, inside a call's `input`
    "work/ask.rs Choice",      // what an answer's option names, read from it
];

/// The wire types: what [`declared`] finds, less [`NOT_WIRE`].
fn wire_declared() -> Vec<(String, bool)> {
    declared()
        .into_iter()
        .filter(|(f, n, _)| !NOT_WIRE.contains(&format!("{f} {n}").as_str()))
        .map(|(_, n, ts)| (n, ts))
        .collect()
}

#[test]
fn every_source_file_is_read_and_the_list_of_others_cannot_rot() {
    let dir = std::env::temp_dir().join(format!("theseus-ts-declared-{}", std::process::id()));
    std::fs::create_dir_all(dir.join("fresh")).unwrap();
    std::fs::write(
        dir.join("fresh/later.rs"),
        "/// New.\npub struct Later {}\n",
    )
    .unwrap();
    let found = declared_in(&dir);
    std::fs::remove_dir_all(&dir).unwrap();
    assert_eq!(
        found,
        [("fresh/later.rs".to_string(), "Later".to_string(), false)]
    );
    let all: Vec<String> = declared()
        .iter()
        .map(|(f, n, _)| format!("{f} {n}"))
        .collect();
    for other in NOT_WIRE {
        assert!(
            all.iter().any(|d| d == other),
            "no source declares {other}: take it off NOT_WIRE"
        );
    }
}

